/**
 * Board List Component
 * Shows available boards to select from
 */

import { createElement, clearElement } from "../lib/dom";
import { widgetStore, actions } from "../lib/state";
import { getClient } from "../lib/api";

export async function renderBoardList(container: HTMLElement) {
  clearElement(container);

  const client = getClient();
  if (!client) {
    container.textContent = "Widget not initialized";
    return;
  }

  // Loading state
  const loadingDiv = createElement("div", { className: "uv-loading" });
  const spinner = createElement("div", { className: "uv-spinner" });
  loadingDiv.appendChild(spinner);
  container.appendChild(loadingDiv);

  try {
    // Fetch boards
    const boards = await client.getBoards();
    actions.setBoards(boards);

    clearElement(container);

    if (boards.length === 0) {
      const emptyDiv = createElement("div", { className: "uv-empty" }, [
        "No boards available",
      ]);
      container.appendChild(emptyDiv);
      return;
    }

    // If only one board, go directly to it
    if (boards.length === 1) {
      await selectBoard(boards[0]._id);
      return;
    }

    // Board selection
    const boardList = createElement("div", { className: "uv-card-list" });

    boards.forEach((board: any) => {
      const boardCard = createElement("div", { className: "uv-card" });
      boardCard.style.cursor = "pointer";

      const title = createElement("h3", { className: "uv-card-title" }, [board.name]);
      const description = createElement("p", { className: "uv-card-description" }, [
        board.description || "Click to view",
      ]);

      boardCard.appendChild(title);
      if (board.description) {
        boardCard.appendChild(description);
      }

      boardCard.addEventListener("click", () => selectBoard(board._id));

      boardList.appendChild(boardCard);
    });

    container.appendChild(boardList);
  } catch (error: any) {
    clearElement(container);
    const errorDiv = createElement("div", { className: "uv-error" }, [
      error.message || "Failed to load boards",
    ]);
    container.appendChild(errorDiv);
  }
}

async function selectBoard(boardId: string) {
  const client = getClient();
  if (!client) return;

  actions.setLoading(true);

  try {
    const [boardData, items] = await Promise.all([
      client.getBoardWithColumns(boardId),
      client.getBoardItems(boardId),
    ]);

    if (boardData) {
      actions.selectBoard(boardId, boardData.board, boardData.columns, items);

      // Fetch user votes if authenticated
      const currentState = widgetStore.get();
      if (currentState.isAuthenticated) {
        const votes = await client.getUserVotes(boardId);
        actions.setUserVotes(votes);
      }
    }
  } catch (error: any) {
    actions.setError(error.message || "Failed to load board");
  } finally {
    actions.setLoading(false);
  }
}
